def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    blocks=[]
    seen=set()
    for r in range(h-2):
        for c in range(w-2):
            color=grid[r][c]
            if color and all(grid[y][x]==color for y in range(r,r+3) for x in range(c,c+3)):
                if (r,c,color) not in seen:
                    seen.add((r,c,color)); blocks.append((r+1,c+1,color))
    lines={}
    for r,c,color in blocks:
        for x in range(w): lines.setdefault((r,x),set()).add(color)
        for y in range(h): lines.setdefault((y,c),set()).add(color)
    for (r,c),colors in lines.items():
        if len(colors)>1: out[r][c]=0
        else:
            color=next(iter(colors))
            out[r][c]=color
    return out
